cypress_script:
describe('Add and Remove Elements', () => {
  it('should add an element when button is clicked', () => {
    cy.visit('https://the-internet.herokuapp.com/add_remove_elements/');
    cy.get('button').contains('Add Element').click();
    cy.get('#elements').children().should('have.length', 1);
  });

  it('should not remove elements if none are present', () => {
    cy.visit('https://the-internet.herokuapp.com/add_remove_elements/');
    cy.get('#elements').children().should('have.length', 0);
    cy.get('button').contains('Add Element').click();
    cy.get('#elements').children().should('have.length', 1);
    cy.get('#elements').children().first().click();
    cy.get('#elements').children().should('have.length', 0);
    cy.get('#elements').children().should('have.length', 0);
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Add and Remove Elements', () => {
  test('should add an element when button is clicked', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/add_remove_elements/');
    await page.click('button:has-text("Add Element")');
    const elements = await page.locator('#elements').count();
    expect(elements).toBe(1);
  });

  test('should not remove elements if none are present', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/add_remove_elements/');
    const elementsBefore = await page.locator('#elements').count();
    expect(elementsBefore).toBe(0);
    await page.click('button:has-text("Add Element")');
    const elementsAfterAdd = await page.locator('#elements').count();
    expect(elementsAfterAdd).toBe(1);
    await page.locator('#elements').first().click();
    const elementsAfterRemove = await page.locator('#elements').count();
    expect(elementsAfterRemove).toBe(0);
  });
});
